create or replace function public.project_checkout_purchase(p_checkout_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare c record; t record; s record; sid text; begin select * into c from public.checkout_sessions where id=p_checkout_id for update; if not found then raise exception 'checkout_not_found'; end if; select * into t from public.gateway_transactions where user_id=c.user_id and (metadata->>'checkout_id')=p_checkout_id::text order by created_at desc limit 1; if not found then return jsonb_build_object('ok',false,'reason','transaction_not_found'); end if; if t.status <> 'approved' then return jsonb_build_object('ok',false,'reason','transaction_not_approved','status',t.status); end if; sid:=coalesce(t.external_id,p_checkout_id::text); insert into public.sales(id,user_id,funnel_id,product_id,checkout_id,transaction_id,amount,currency,status,attribution,source,medium,campaign,content,term,click_id,external_id,gateway_id,occurred_at,data) values(sid,c.user_id,c.funnel_id,c.product_id,c.id,t.id,t.amount,t.currency,'approved',c.attribution,c.attribution->>'source',c.attribution->>'medium',c.attribution->>'campaign',c.attribution->>'content',c.attribution->>'term',c.attribution->>'click_id',t.external_id,t.gateway_id,coalesce(t.completed_at,now()),jsonb_build_object('projected_by','project_checkout_purchase')) on conflict (id) do update set transaction_id=excluded.transaction_id,checkout_id=excluded.checkout_id,status=excluded.status,amount=excluded.amount,currency=excluded.currency,attribution=excluded.attribution,gateway_id=excluded.gateway_id,occurred_at=excluded.occurred_at; update public.checkout_sessions set status='completed',completed_at=coalesce(completed_at,now()),updated_at=now() where id=c.id; return jsonb_build_object('ok',true,'sale_id',sid,'transaction_id',t.id,'checkout_id',c.id); end; $$; revoke execute on function public.project_checkout_purchase(uuid) from public,anon,authenticated; grant execute on function public.project_checkout_purchase(uuid) to service_role;